import argparse
import json
from pathlib import Path

parser = argparse.ArgumentParser()
parser.add_argument('--check', action='store_true')
args = parser.parse_args()
root = Path(__file__).resolve().parent.parent
files = sorted((root / 'db' / 'migrations').glob('*.sql'))
if not files:
    raise SystemExit('No authoritative migrations found')
lines = [
    '// Code generated by scripts/generate-go-backend-schema.py. DO NOT EDIT.',
    '',
    'package backendstore',
    '',
    'type migration struct { tag, sql string }',
    '',
    'var migrations = []migration{',
]
for source in files:
    sql = source.read_text(encoding='utf-8')
    lines.append('\t{' + json.dumps(source.stem) + ', ' + json.dumps(sql, ensure_ascii=False) + '},')
lines += ['}', '']
text = '\n'.join(lines)
target = root / 'fintwind-go' / 'internal' / 'backendstore' / 'schema_generated.go'
if args.check:
    if not target.is_file() or target.read_text(encoding='utf-8') != text:
        raise SystemExit('Generated Go migrations differ from authoritative SQL')
    print('[OK] Go migrations match authoritative SQL')
else:
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(text, encoding='utf-8', newline='\n')
    print('[OK] Generated Go migrations')
